head.b:skin:
/* =====================================================
   AMAZONIKA BLOGGER THEME
   Version : 0.1
===================================================== */

:root{

--primary:#0F766E;

--secondary:#14B8A6;

--accent:#F59E0B;

--danger:#EF4444;

--success:#22C55E;

--dark:#111827;

--light:#F8FAFC;

--gray:#64748B;

--radius:18px;

--shadow:
0 10px 40px rgba(0,0,0,.08);

}

*{

margin:0;

padding:0;

box-sizing:border-box;

}

body{

font-family:'Cairo',sans-serif;

background:#ffffff;

color:#1e293b;

line-height:1.8;

}

a{

text-decoration:none;

color:inherit;

}

img{

max-width:100%;

display:block;

}

.wrapper{

width:min(1400px,95%);

margin:auto;

}
